<?php require 'includes/header.php';require 'config/db.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$sid=(int)$_POST['student_id'];$amount=(float)$_POST['amount'];$paid=(float)$_POST['paid'];$bal=$amount-$paid;$date=$_POST['payment_date'];$q=$conn->prepare("INSERT INTO fees(student_id,amount,paid,balance,payment_date) VALUES(?,?,?,?,?)");$q->bind_param('iddds',$sid,$amount,$paid,$bal,$date);$q->execute();header('Location:fees.php');exit;}
$students=$conn->query("SELECT id,student_id,first_name,last_name FROM students");$rows=$conn->query("SELECT f.*,s.first_name,s.last_name FROM fees f JOIN students s ON s.id=f.student_id ORDER BY f.id DESC");?>
<div class="d-flex justify-content-between mb-3"><h3>Fees</h3><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#add">+ Add Payment</button></div>
<div class="card p-3"><table class="table"><tr><th>Student</th><th>Amount</th><th>Paid</th><th>Balance</th><th>Date</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=$r['first_name'].' '.$r['last_name']?></td><td><?=$r['amount']?></td><td><?=$r['paid']?></td><td><?=$r['balance']?></td><td><?=$r['payment_date']?></td></tr><?php endwhile;?></table></div>
<div class="modal fade" id="add"><div class="modal-dialog"><div class="modal-content"><form method="post"><div class="modal-header"><h5>Fees Payment</h5></div><div class="modal-body"><select name="student_id" class="form-select mb-2" required><option value="">Student</option><?php while($s=$students->fetch_assoc()):?><option value="<?=$s['id']?>"><?=$s['student_id'].' - '.$s['first_name'].' '.$s['last_name']?></option><?php endwhile;?></select><input name="amount" type="number" step="0.01" class="form-control mb-2" placeholder="Total amount" required><input name="paid" type="number" step="0.01" class="form-control mb-2" placeholder="Paid" required><input name="payment_date" type="date" class="form-control" value="<?=date('Y-m-d')?>"></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div></div><?php require 'includes/footer.php'; ?>